const stages={
  wear:{number:'01',label:'WEARABLE SIGNAL',title:'Continuous ECG capture',heading:'Comfortable acquisition',copy:'The patch is designed to make extended ECG collection less intrusive during normal daily routines.',wave:'M0 120H78L93 112L105 124L119 120L133 70L146 174L162 115L184 120H272L287 111L300 124L314 120L329 72L342 172L358 115L380 120H468L483 111L497 124L511 120L526 69L539 175L555 115L578 120H666L681 111L695 124L709 120L724 74L738 168L752 116L760 120'},
  connect:{number:'02',label:'CONNECTED DATA PATH',title:'Mobile and cloud transfer',heading:'Data where it is needed',copy:'Bluetooth and mobile connectivity provide a pathway from the wearable device to secure processing and authorised access.',wave:'M0 145C70 145 70 90 140 90S210 150 280 130S350 68 420 92S500 155 570 108S650 78 760 88'},
  review:{number:'03',label:'AI-ASSISTED REVIEW',title:'Patterns organised for review',heading:'Support for expert interpretation',copy:'Signal-processing and classification research aims to help reviewers navigate long recordings more efficiently.',wave:'M0 155H95V118H190V140H285V74H380V124H475V95H570V135H665V83H760'}
};
const tabs=[...document.querySelectorAll('[role="tab"]')];
tabs.forEach(tab=>tab.addEventListener('click',()=>{tabs.forEach(t=>t.setAttribute('aria-selected',String(t===tab)));const s=stages[tab.dataset.stage];document.querySelector('#journey-panel').setAttribute('aria-labelledby',tab.id);document.querySelector('#stage-number').textContent=s.number;document.querySelector('#signal-label').textContent=s.label;document.querySelector('#signal-title').textContent=s.title;document.querySelector('#stage-title').textContent=s.heading;document.querySelector('#stage-copy').textContent=s.copy;const wave=document.querySelector('#wave');wave.setAttribute('d',s.wave);wave.style.animation='none';requestAnimationFrame(()=>wave.style.animation='')}));
const menu=document.querySelector('.menu'),nav=document.querySelector('#nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));nav.classList.toggle('open',!open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
